ALTER POLICY "characters read own or mestra" ON public.characters USING (public.is_member(campaign_id, auth.uid()) AND (owner_id = auth.uid() OR public.is_mestra(campaign_id, auth.uid())));
ALTER POLICY "characters update own or mestra" ON public.characters USING (public.is_member(campaign_id, auth.uid()) AND (owner_id = auth.uid() OR public.is_mestra(campaign_id, auth.uid()))) WITH CHECK (public.is_member(campaign_id, auth.uid()) AND (owner_id = auth.uid() OR public.is_mestra(campaign_id, auth.uid())));
ALTER POLICY "characters delete own or mestra" ON public.characters USING (public.is_member(campaign_id, auth.uid()) AND (owner_id = auth.uid() OR public.is_mestra(campaign_id, auth.uid())));
ALTER POLICY char_items_read ON public.character_items USING (public.is_member(campaign_id, auth.uid()) AND (public.is_mestra(campaign_id, auth.uid()) OR EXISTS (SELECT 1 FROM public.characters c WHERE c.id = character_id AND c.campaign_id = character_items.campaign_id AND c.owner_id = auth.uid())));
CREATE OR REPLACE FUNCTION public.can_see_item(_item uuid, _user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.items i WHERE i.id = _item AND public.is_member(i.campaign_id,_user) AND (public.is_mestra(i.campaign_id,_user) OR EXISTS (SELECT 1 FROM public.character_items ci JOIN public.characters c ON c.id=ci.character_id WHERE ci.item_id=i.id AND ci.campaign_id=i.campaign_id AND c.campaign_id=i.campaign_id AND c.owner_id=_user))) $$;
REVOKE EXECUTE ON FUNCTION public.add_owner_as_mestra(), public.campaign_guard(), public.characters_guard(), public.handle_new_user(), public.members_guard(), public.sheet_structure_guard(), public.items_guard() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.is_member(uuid,uuid), public.is_mestra(uuid,uuid), public.shares_campaign(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_member(uuid,uuid), public.is_mestra(uuid,uuid), public.shares_campaign(uuid,uuid) TO authenticated, service_role;